Um **vetor** é um par de números (x, y). Os jogos o usam para uma **posição** (onde), uma **velocidade** (com que rapidez e em que sentido) e uma **aceleração** (como a velocidade muda). Toda engine e biblioteca de matemática tem um (`glm::vec2`, o `Vector2` do raylib, o `FVector2D` da Unreal); este curso faz o `Vec2` da lição de C++ crescer até virar um pequeno header, e os trechos daqui em diante o incluem:

```cpp
// vec2.h
#pragma once
#include <cmath>
#include <ostream>

struct Vec2 {
    float x = 0, y = 0;

    Vec2& operator+=(Vec2 o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(Vec2 o) { x -= o.x; y -= o.y; return *this; }

    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalized() const {
        float len = length();
        return len > 0 ? Vec2{x / len, y / len} : *this;
    }
};

inline Vec2 operator+(Vec2 a, Vec2 b) { return {a.x + b.x, a.y + b.y}; }
inline Vec2 operator-(Vec2 a, Vec2 b) { return {a.x - b.x, a.y - b.y}; }
inline Vec2 operator*(Vec2 v, float k) { return {v.x * k, v.y * k}; }
inline Vec2 operator/(Vec2 v, float k) { return {v.x / k, v.y / k}; }
inline float dot(Vec2 a, Vec2 b) { return a.x * b.x + a.y * b.y; }

inline std::ostream& operator<<(std::ostream& os, Vec2 v) {
    return os << '(' << v.x << ", " << v.y << ')';
}
```

São dois floats, então ele é passado **por valor** em todo lugar, e o `operator<<` o imprime como `(x, y)`.

