#include <algorithm>
#include <iostream>
#include "vec2.h"

struct Box { float minX, minY, maxX, maxY; };

Vec2 pushOut(Box mover, Box wall) {
    float overlapX = std::min(mover.maxX, wall.maxX) - std::max(mover.minX, wall.minX);
    float overlapY = std::min(mover.maxY, wall.maxY) - std::max(mover.minY, wall.minY);
    if (overlapX <= 0 || overlapY <= 0) return {0, 0};   // not touching

    bool moverIsLeft = mover.minX + mover.maxX < wall.minX + wall.maxX;
    bool moverIsBelow = mover.minY + mover.maxY < wall.minY + wall.maxY;
    if (overlapX < overlapY) return {moverIsLeft ? -overlapX : overlapX, 0};
    return {0, moverIsBelow ? -overlapY : overlapY};
}

